        },
        {
          "name": "陈墨",
          "category": "character",
          "description": "成年保管员陈墨，身穿蓝色工作服，神情专注，身体朝向林岚身旁站立，准备迎接钥匙。"
        },
        {
          "name": "铜钥匙",
          "category": "prop",
          "description": "带有岁月的陈旧铜钥匙，金属材质泛着微光，初始由林岚右手持有，随后交予陈墨右手。"
        }
      ],
      "visibleAssets": [
        "废弃医院",
        "林岚",
        "陈墨",
        "铜钥匙"
